<?php use AgendaShops\Http\Forms as F; ?>
<main class="page-shell"><span class="pill">Administração</span><h1>Operação e confiança</h1>
<div class="service-grid"><?php foreach ($page['metrics'] as $label=>$count): ?><article class="card"><h2><?= (int)$count ?></h2><p><?= e($label) ?></p></article><?php endforeach; ?></div>
<section class="card"><h2>Estabelecimentos</h2><?php if (!$page['businesses']): ?><p>Nenhum estabelecimento cadastrado.</p><?php endif; ?>
<?php foreach ($page['businesses'] as $b): ?><details><summary><?= e($b['name'] . ' · ' . $b['status']) ?></summary><p><?= e($b['description']) ?></p><p><?= e($b['address'] . ' · ' . $b['city'] . ' · ' . $b['phone']) ?></p>
<?= F::open('moderate',['type'=>'business','id'=>$b['id']],'/admin') . F::select('value','Decisão',['APPROVED'=>'Aprovar','REJECTED'=>'Recusar','SUSPENDED'=>'Suspender'],$b['status']) . F::close('Aplicar decisão') ?></details><?php endforeach; ?></section>
<section class="card"><h2>Categorias e subcategorias</h2>
<?php foreach (array_merge($page['categories'],[['id'=>'','name'=>'','parent_id'=>'','sort_order'=>0,'active'=>1]]) as $category): ?><details><summary><?= $category['id'] ? e($category['name']) : 'Adicionar categoria' ?></summary>
<?= F::open('category',['id'=>$category['id']],'/admin') . F::input('name','Nome',$category['name'],'text','required') . F::select('parent_id','Categoria superior',[''=>'Nenhuma'] + array_column(array_filter($page['categories'],fn($c)=>!$c['parent_id'] && $c['id'] !== $category['id']),'name','id'),$category['parent_id'] ?? '','') . F::input('sort_order','Ordem',(string)$category['sort_order'],'number','required min="0" max="9999"') . F::check('active','Ativa',(bool)$category['active']) . F::close() ?></details><?php endforeach; ?></section>
<section class="card"><h2>Denúncias</h2><?php if (!$page['reports']): ?><p>Nenhuma denúncia recebida.</p><?php endif; ?>
<?php foreach ($page['reports'] as $report): ?><article><h3><?= e($report['target_type'] . ' · ' . $report['status']) ?></h3><p>Referência: <?= e($report['target_id']) ?></p><p><?= e($report['reason']) ?></p>
<?php if ($report['status'] === 'OPEN'): ?><?= F::open('moderate',['type'=>'report','id'=>$report['id'],'value'=>'RESOLVED'],'/admin') . F::close('Marcar como resolvida') ?><?php endif; ?></article><?php endforeach; ?></section>
<section class="card"><h2>Moderação de avaliações</h2><?php foreach ($page['reviews'] as $review): ?><details><summary><?= (int)$review['rating'] ?>/5 · <?= e($review['id']) ?></summary><p><?= e($review['body']) ?></p><?= F::open('moderate',['type'=>'review','id'=>$review['id'],'value'=>$review['visible'] ? '0' : '1'],'/admin') . F::close($review['visible'] ? 'Ocultar avaliação' : 'Exibir avaliação') ?></details><?php endforeach; ?></section>
<section class="card"><h2>Bloqueio de conversas</h2><?php foreach ($page['conversations'] as $conversation): ?><details><summary><?= e($conversation['service_name'] . ' · ' . $conversation['id']) ?></summary><p>Estado: <?= $conversation['blocked'] ? 'Bloqueada' : 'Aberta' ?></p><a href="/admin/conversas/<?= e($conversation['id']) ?>">Inspecionar conversa</a><?= F::open('moderate',['type'=>'conversation','id'=>$conversation['id'],'value'=>$conversation['blocked'] ? '0' : '1'],'/admin') . F::close($conversation['blocked'] ? 'Desbloquear' : 'Bloquear conversa') ?></details><?php endforeach; ?></section>
<section class="card"><h2>Auditoria</h2><div class="table-scroll"><table><thead><tr><th>Data (Brasília)</th><th>Responsável</th><th>Ação</th><th>Referência</th></tr></thead><tbody><?php foreach ($page['audit'] as $event): ?><tr><td><?= e(localDate($event['created_at'])) ?></td><td><?= e($event['name']) ?></td><td><?= e($event['action']) ?></td><td><?= e($event['target_id']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
</main>
